INSERT INTO MB_USER (
	UPDATED_AT 
	, ENABLED
	, UID
	, ROLE
	, PROVIDER
	, ID 
	, EMAIL 
	, NICKNAME 
	, PROFILE_IMG_PATH 
	, DESCRIPTION 
) VALUES (
	CURRENT_TIMESTAMP
	, #{enabled}
	, #{uid}
	, #{role}
	, #{provider}
	, #{id}
	, #{email, typeHandler=com.utime.memoBom.common.typeHandler.SeedEncryptTypeHandler} 
	, #{nickname} 
	, #{profileUrl} 
	, #{dscr} 
)

INSERT INTO MB_USER_LOGIN_RECORD (
	USER_NO
	, IP
	, DEVICE

	, MODEL

) VALUES (
	#{user.userNo}
	, #{ip}
	, #{device.device}

	, #{device.model}

)

mapper.select:

SELECT

    (SELECT COUNT(*)
       FROM MB_TOPIC TP
      WHERE TP.OWNER_NO = #{userNo}
        AND TP.ENABLED = 1
    ) AS "topicCreatedCount",


    (SELECT COUNT(*)
       FROM MB_TOPIC_FOLLOW FL
      WHERE FL.USER_NO = #{userNo}
    ) AS "topicFollowCount",


    (SELECT COUNT(*)
       FROM MB_USER_LOGIN_RECORD LR
      WHERE LR.USER_NO = #{userNo}
    ) AS "loginCount",


    (SELECT COUNT(*)
       FROM MB_FRAGMENT F
      WHERE F.USER_NO = #{userNo}
        AND F.IS_DELETED = 0
    ) AS "fragmentWriteCount",


    (SELECT COUNT(*)
       FROM MB_FRAGMENT_COMMENTS C
      WHERE C.USER_NO = #{userNo}
    ) AS "commentWriteCount",


    (SELECT COUNT(*)
       FROM MB_FRAGMENT_EMOTION_LOG E
      WHERE E.USER_NO = #{userNo}
        AND E.TARGET_TYPE = 1
    ) AS "fragmentEmotionCount",


    (SELECT COUNT(*)
       FROM MB_FRAGMENT_EMOTION_LOG E
      WHERE E.USER_NO = #{userNo}
        AND E.TARGET_TYPE = 2
    ) AS "commentEmotionCount"

mapper.update:
UPDATE MB_USER SET
	FONT_SIZE = #{fs, typeHandler=com.utime.memoBom.user.typeHandler.EFontSizeTypeHandler}
WHERE USER_NO = #{user.userNo} AND ENABLED = 1

mapper.select:
 		SELECT 
		    CASE WHEN EXISTS (
		        SELECT 1
		        FROM MB_USER US
		        INNER JOIN MB_PUSH_SUB PU ON US.USER_NO = PU.USER_NO
		        WHERE US.USER_NO = #{user.userNo}
		          AND US.ENABLED = 1 
		          AND PU.DEVICE_ID = #{deviceId}  
		          AND US.PUSH_ENABLED = 1
		    ) THEN 1 ELSE 0 END AS PUSH_ENABLED

SELECT UID , DATETIME(CREATE_AT,'localtime') AS CREATE_AT , DATETIME(READ_AT,'localtime') AS READ_AT , ALARM_TYPE , TITLE , MESSAGE , URL FROM MB_ALARM WHERE 1=1 AND USER_NO = #{user.userNo}
AND ( TITLE LIKE '%' || #{keyword} || '%' OR MESSAGE LIKE '%' || #{keyword} || '%' )
ORDER BY ALARM_NO DESC LIMIT 10 OFFSET (#{pageNo} - 1) * 10
